-- TP2 Food Store - restricciones de negocio
-- Ejecutar sobre una copia del esquema, dentro de BEGIN ... ROLLBACK primero.

-- R1: un pedido no puede regresar a PENDIENTE ni cambiar después de ENTREGADO/CANCELADO.
CREATE OR REPLACE FUNCTION validar_transicion_estado_pedido()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.estado = OLD.estado THEN
        RETURN NEW;
    END IF;

    IF (OLD.estado = 'PENDIENTE' AND NEW.estado IN ('CONFIRMADO', 'CANCELADO'))
       OR (OLD.estado = 'CONFIRMADO' AND NEW.estado IN ('ENTREGADO', 'CANCELADO')) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Transición de estado no permitida: % -> %', OLD.estado, NEW.estado
        USING ERRCODE = '23514';
END;
$$;

DROP TRIGGER IF EXISTS trg_validar_transicion_estado_pedido ON pedido;
CREATE TRIGGER trg_validar_transicion_estado_pedido
BEFORE UPDATE OF estado ON pedido
FOR EACH ROW
EXECUTE FUNCTION validar_transicion_estado_pedido();

-- R2: un detalle sólo puede agregarse, modificarse o borrarse mientras el pedido está PENDIENTE.
CREATE OR REPLACE FUNCTION validar_edicion_detalle_pedido()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_id_pedido INTEGER;
    v_ids INTEGER[];
    v_estado estado_pedido;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_ids := ARRAY[NEW.id_pedido];
    ELSIF TG_OP = 'DELETE' THEN
        v_ids := ARRAY[OLD.id_pedido];
    ELSE
        -- Mover una línea modifica tanto el pedido de origen como el de destino.
        v_ids := ARRAY[OLD.id_pedido, NEW.id_pedido];
    END IF;

    -- Orden fijo para que dos traslados no tomen los pedidos en orden inverso.
    FOR v_id_pedido IN
        SELECT DISTINCT id FROM unnest(v_ids) AS ids(id) ORDER BY id
    LOOP
        SELECT estado INTO v_estado
        FROM pedido
        WHERE id_pedido = v_id_pedido
        FOR SHARE;

        -- FOR SHARE bloquea también UPDATE de estado. FOR KEY SHARE no lo hacía.
        IF NOT FOUND THEN
            RAISE EXCEPTION 'El pedido % no existe', v_id_pedido USING ERRCODE = '23503';
        END IF;

        IF v_estado <> 'PENDIENTE' THEN
            RAISE EXCEPTION 'No se puede editar el detalle del pedido % porque está %', v_id_pedido, v_estado
                USING ERRCODE = '23514';
        END IF;
    END LOOP;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_validar_edicion_detalle_pedido ON detalle_pedido;
CREATE TRIGGER trg_validar_edicion_detalle_pedido
BEFORE INSERT OR UPDATE OR DELETE ON detalle_pedido
FOR EACH ROW
EXECUTE FUNCTION validar_edicion_detalle_pedido();

-- R3: el detalle sólo admite productos activos y una cantidad que no exceda su stock actual.
-- FOR SHARE evita que una actualización concurrente del producto cambie esa fila durante la validación.
CREATE OR REPLACE FUNCTION validar_producto_y_stock_detalle()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_stock INTEGER;
    v_activo BOOLEAN;
BEGIN
    SELECT stock, activo INTO v_stock, v_activo
    FROM producto
    WHERE id_producto = NEW.id_producto
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El producto % no existe', NEW.id_producto USING ERRCODE = '23503';
    END IF;

    IF NOT v_activo THEN
        RAISE EXCEPTION 'El producto % está inactivo', NEW.id_producto USING ERRCODE = '23514';
    END IF;

    IF NEW.cantidad > v_stock THEN
        RAISE EXCEPTION 'Stock insuficiente para el producto %: solicitado %, disponible %',
            NEW.id_producto, NEW.cantidad, v_stock USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_validar_producto_y_stock_detalle ON detalle_pedido;
CREATE TRIGGER trg_validar_producto_y_stock_detalle
BEFORE INSERT OR UPDATE OF id_producto, cantidad ON detalle_pedido
FOR EACH ROW
EXECUTE FUNCTION validar_producto_y_stock_detalle();

-- Total histórico: precio de venta y cantidad, incluso después de bajas del catálogo.
CREATE FUNCTION public.tpi_total_pedido(p_id_pedido integer)
RETURNS numeric
LANGUAGE plpgsql STABLE SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_total numeric;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.pedido WHERE id_pedido = p_id_pedido) THEN
        RAISE EXCEPTION 'Pedido inexistente: %', p_id_pedido USING ERRCODE = 'P0002';
    END IF;
    SELECT COALESCE(sum(cantidad * precio_unitario), 0)
    INTO v_total
    FROM public.detalle_pedido WHERE id_pedido = p_id_pedido;
    RETURN v_total;
END;
$$;

-- El llamador controla BEGIN/COMMIT/ROLLBACK. No hay confirmaciones parciales.
-- JSONB: [{"id_producto": 1, "cantidad": 2}, ...]. No acepta precios del cliente.
CREATE PROCEDURE public.tpi_registrar_pedido(
    IN p_cliente_id integer,
    IN p_forma_pago public.forma_pago,
    IN p_lineas jsonb,
    INOUT p_id_pedido integer DEFAULT NULL
)
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_linea jsonb;
    v_producto record;
BEGIN
    IF p_id_pedido IS NOT NULL THEN
        RAISE EXCEPTION 'El id de salida debe recibirse como NULL' USING ERRCODE = '22023';
    END IF;
    IF jsonb_typeof(p_lineas) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Las líneas deben ser un arreglo JSONB' USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(p_lineas) = 0 THEN
        RAISE EXCEPTION 'El pedido necesita al menos una línea' USING ERRCODE = '22023';
    END IF;
    FOR v_linea IN SELECT value FROM jsonb_array_elements(p_lineas) LOOP
        IF jsonb_typeof(v_linea) IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION 'Cada línea debe ser un objeto' USING ERRCODE = '22023';
        END IF;
        IF jsonb_typeof(v_linea->'id_producto') IS DISTINCT FROM 'number'
           OR jsonb_typeof(v_linea->'cantidad') IS DISTINCT FROM 'number'
           OR ((v_linea->>'id_producto') ~ '^[1-9][0-9]*$') IS NOT TRUE
           OR ((v_linea->>'cantidad') ~ '^[1-9][0-9]*$') IS NOT TRUE
           OR v_linea - ARRAY['id_producto','cantidad'] <> '{}'::jsonb THEN
            RAISE EXCEPTION 'Usar solo id_producto y cantidad, enteros positivos' USING ERRCODE = '22023';
        END IF;
        IF (v_linea->>'id_producto')::numeric > 2147483647
           OR (v_linea->>'cantidad')::numeric > 2147483647 THEN
            RAISE EXCEPTION 'Identificador o cantidad fuera del rango INTEGER' USING ERRCODE = '22023';
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_lineas) e
               GROUP BY (e->>'id_producto')::integer HAVING count(*) > 1) THEN
        RAISE EXCEPTION 'Un producto no puede repetirse en el pedido' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.pedido(cliente_id, forma_pago, estado)
    VALUES (p_cliente_id, p_forma_pago, 'PENDIENTE') RETURNING id_pedido INTO p_id_pedido;

    FOR v_linea IN SELECT value FROM jsonb_array_elements(p_lineas)
                  ORDER BY (value->>'id_producto')::integer LOOP
        SELECT id_producto, precio_lista INTO v_producto
        FROM public.producto WHERE id_producto = (v_linea->>'id_producto')::integer
        FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Producto inexistente: %', v_linea->>'id_producto' USING ERRCODE = '23503';
        END IF;
        -- Los triggers validan estado, vigencia de producto/categoría y stock.
        INSERT INTO public.detalle_pedido(id_pedido, id_producto, precio_unitario, cantidad)
        VALUES (p_id_pedido, v_producto.id_producto, v_producto.precio_lista,
                (v_linea->>'cantidad')::integer);
    END LOOP;
END;
$$;

-- Baja lógica idempotente. Mantiene la fila, su nombre único y su historia de ventas.
CREATE PROCEDURE public.tpi_baja_producto(IN p_id_producto integer)
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
BEGIN
    UPDATE public.producto SET activo = false WHERE id_producto = p_id_producto;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Producto inexistente: %', p_id_producto USING ERRCODE = 'P0002';
    END IF;
END;
$$;

